private int parseEndOfLine(String headerPart, int end) {
    if (headerPart == null) {
        throw new IllegalArgumentException("headerPart cannot be null");
    }
    if (end < 0 || end > headerPart.length()) {
        throw new IllegalArgumentException("end index is out of bounds");
    }

    for (int i = end; i < headerPart.length() - 1; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
    }
    return -1; // Return -1 if no \r\n sequence is found
}

