    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }
    return new IsomorphicGraphMapping<V,E>() {
        @Override
        public V getVertexCorrespondence(V vertex, boolean forward) {
            if (vertex == null || !graph.containsVertex(vertex)) {
                throw new IllegalArgumentException("Vertex is not part of the graph");
            }
            return vertex;
        }

        @Override
        public E getEdgeCorrespondence(E edge, boolean forward) {
            if (edge == null || !graph.containsEdge(edge)) {
                throw new IllegalArgumentException("Edge is not part of the graph");
            }
            return edge;
        }

        @Override
        public boolean isIdentity() {
            return true;
        }
    };
}

