public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Arguments cannot be null");
    }

    // Get the size of the message
    int size = schema.getSerializedSize(message, buffer);
    if (size < 0) {
        throw new IOException("Invalid size for the message");
    }

    // Write the length prefix as a varint
    int varintSize = writeVarint32(out, size);
    if (varintSize < 0) {
        throw new IOException("Failed to write the message length");
    }

    // Serialize the message
    int serializedSize = schema.writeTo(out, message, buffer);
    if (serializedSize != size) {
        throw new IOException("Serialized size does not match expected size");
    }

    // Return the total size written (length prefix + message)
    return varintSize + serializedSize;
}

private static int writeVarint32(OutputStream out, int value) throws IOException {
    if (value >= 0) {
        out.write(value);
        return 1;
    }
    int i = 0;
    while ((value & 0xFFFFFF80) != 0) {
        out.write((value & 0x7F) | 0x80);
        value >>>= 7;
        i++;
    }
    out.write(value);
    return i + 1;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    final byte[] data;
    try {
        data = schema.writeTo(buffer, message);
    } finally {
        buffer.clear();
    }

    final int size = data.length;
    writeRawVarint32(out, size);
    out.write(data);

    return size;
}

private static void writeRawVarint32(OutputStream out, int value) throws IOException {
    while ((value & ~0x7F) != 0) {
        out.write((value & 0x7F) | 0x80);
        value >>>= 7;
    }
    out.write(value & 0x7F);
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Parameters out, message, schema, and buffer cannot be null");
    }

    try {
        // Compute the size of the message
        int size = schema.getSerializedSize(message, buffer);

        // Write the size as a varint
        ProtobufOutput output = new ProtobufOutput(out);
        output.writeRawVarInt32(size);

        // Serialize the message
        schema.writeTo(output, message, buffer);
        output.flush();

        return size;
    } catch (IOException e) {
        throw e;
    } catch (Exception e) {
        throw new IOException("Error serializing message", e);
    }
