public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    // First, calculate the size of the message
    int size = schema.getSerializedSize(message, buffer);

    // Allocate a buffer for the size (varint32)
    LinkedBuffer sizeBuffer = buffer.next;
    try {
        buffer.next = null;
        final byte[] sizeBytes = new byte[10];
        int sizeLength = CodedOutputStream.computeUInt32SizeNoTag(size);
        CodedOutputStream sizeOut = CodedOutputStream.newInstance(sizeBytes);
        sizeOut.writeUInt32NoTag(size);
        sizeOut.flush();

        // Write the size to the output stream
        out.write(sizeBytes, 0, sizeLength);

        // Write the message to the output stream
        buffer.next = sizeBuffer;
        schema.writeTo(out, message, buffer);
    } finally {
        if (buffer.next != null) {
            buffer.next = sizeBuffer.next;
            sizeBuffer.next = null;
            buffer.next.clear();
        }
    }

    // Return the total size written (size of message + size of length prefix)
    return size + CodedOutputStream.computeUInt32SizeNoTag(size);
}

