private static Class<?> resolveTypeVariable(Class<?> targetType, TypeVariable<?> typeVariable) {
    Type[] genericInterfaces = targetType.getGenericInterfaces();
    for (Type genericInterface : genericInterfaces) {
        if (!(genericInterface instanceof ParameterizedType)) {
            continue;
        }
        ParameterizedType parameterizedInterface = (ParameterizedType) genericInterface;
        Type rawType = parameterizedInterface.getRawType();
        if (rawType instanceof Class) {
            Class<?> rawClass = (Class<?>) rawType;
            if (rawClass.getTypeParameters().length == parameterizedInterface.getActualTypeArguments().length) {
                TypeVariable<?>[] typeParameters = rawClass.getTypeParameters();
                Type[] actualTypeArguments = parameterizedInterface.getActualTypeArguments();
                for (int i = 0; i < typeParameters.length; i++) {
                    if (typeParameters[i].equals(typeVariable)) {
