static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }

    if (timeBucket < 10000000 || timeBucket > 99991231) {
        throw new IllegalArgumentException("timeBucket must be a valid date in the format YYYYMMDD");
    }

    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Calculate the first day of the month
    long firstDayOfMonth = year * 10000 + month * 100 + 1;

    // Calculate the day of the month part of the compressed time bucket
    int compressedDay = 1 + ((day - 1) / dayStep) * dayStep;

    // Ensure the compressed day does not spill over to the next month
    int daysInMonth = getDaysInMonth(year, month);
    if (compressedDay > daysInMonth) {
        compressedDay = daysInMonth;
    }

    return firstDayOfMonth + compressedDay - 1;
}

private static int getDaysInMonth(int year, int month) {
    if (month == 2) {
        if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
            return 29; // Leap year
        } else {
            return 28;
        }
    }
    return switch (month) {
        case 1, 3, 5, 7, 8, 10, 12 -> 31;
        case 4, 6, 9, 11 -> 30;
        default -> throw new IllegalArgumentException("Invalid month: " + month);
    };
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be a positive integer");
    }
    if (timeBucket < 10000000 || timeBucket > 99991231) {
        throw new IllegalArgumentException("timeBucket must be in the format YYYYMMDD");
    }

    int year = (int) (timeBucket / 10000);
    int monthDay = (int) (timeBucket % 10000);
    int month = monthDay / 100;
    int day = monthDay % 100;

    int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Invalid month in timeBucket");
    }
    if (day < 1 || day > daysInMonth[month - 1]) {
        throw new IllegalArgumentException("Invalid day in timeBucket for the given month");
    }

    int dayOfYear = 0;
    for (int i = 0; i < month - 1; i++) {
        dayOfYear += daysInMonth[i];
    }
    dayOfYear += day;

    int newDayOfYear = (dayOfYear / dayStep) * dayStep + 1;
    if (newDayOfYear > 365) {
        newDayOfYear = 365;
    }

    int newMonth = 0;
    int newDay = 0;
    int cumulativeDays = 0;
    for (int i = 0; i < 12; i++) {
        if (cumulativeDays + daysInMonth[i] >= newDayOfYear) {
            newMonth = i + 1;
            newDay = newDayOfYear - cumulativeDays;
            break;
        }
        cumulativeDays += daysInMonth[i];
    }

    return year * 10000 + newMonth * 100 + newDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }

    try {
        // Extract year, month, and day from the timeBucket
        int year = (int) (timeBucket / 10000);
        int monthDay = (int) (timeBucket % 10000);

        // Convert monthDay to day of the year
        int month = monthDay / 100;
        int day = monthDay % 100;

        // Days in each month (non-leap year)
        int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

        // Check for leap year and adjust February days
        if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
            daysInMonth[1] = 29;
        }

        // Validate month and day
        if (month < 1 || month > 12 || day < 1 || day > daysInMonth[month - 1]) {
            throw new IllegalArgumentException("Invalid date in timeBucket");
        }

        // Calculate day of the year
        int dayOfYear = 0;
        for (int i = 0; i < month - 1; i++) {
            dayOfYear += daysInMonth[i];
        }
        dayOfYear += day;

        // Calculate the new day of the year based on dayStep
        int newDayOfYear = ((dayOfYear - 1) / dayStep) * dayStep + 1;

        // Convert newDayOfYear back to month and day
        int newMonth = 0;
        int newDay = 0;
        for (int i = 0; i < 12; i++) {
            if (newDayOfYear > daysInMonth[i]) {
                newDayOfYear -= daysInMonth[i];
                newMonth++;
            } else {
                newDay = newDayOfYear;
                newMonth++;
                break;
            }
        }

        // Reconstruct the new time bucket
        return year * 10000L + newMonth * 100 + newDay;
    } catch (Exception e) {
        throw new RuntimeException("Failed to compress time bucket", e);
    }
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    if (month < 1 || month > 12 || day < 1 || day > 31) {
        throw new IllegalArgumentException("Invalid date in timeBucket");
    }

    int compressedDay = (day / dayStep) * dayStep;
    if (day % dayStep != 0) {
        compressedDay += dayStep;
    }
    compressedDay = Math.min(compressedDay, getDaysInMonth(year, month));

    return year * 10000 + month * 100 + compressedDay;
}

private static int getDaysInMonth(int year, int month) {
    switch (month) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            return 31;
        case 4: case 6: case 9: case 11:
            return 30;
        case 2:
            if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
                return 29; // Leap year
            } else {
                return 28;
            }
        default:
            throw new IllegalArgumentException("Invalid month");
    }
