    // Validate the day value based on the month and year
    if (month < 1 || month > 12 || day < 1 || day > 31) {
        throw new IllegalArgumentException("Invalid timeBucket format or date");
    }

    // Calculate the new day by stepping back to the nearest dayStep aligned day
    int newDay = day - (day - 1) % dayStep;
    if (newDay == 0) {
        newDay = dayStep;
    }

    return year * 10000L + month * 100L + newDay;
