public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    if (byteLength == 0) {
        return this; // No bytes to put, return as is
    }
    if (byteArrayValue == null) {
        ensureCapacity(byteLength);
        for (int i = 0; i < byteLength; i++) {
            data[size++] = 0;
        }
    } else {
        if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("Invalid byteOffset: " + byteOffset);
        }
        if (byteOffset + byteLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset + byteLength exceeds byteArrayValue length");
        }
        ensureCapacity(byteLength);
        System.arraycopy(byteArrayValue, byteOffset, data, size, byteLength);
        size += byteLength;
    }
    return this;
}

private void ensureCapacity(final int additionalCapacity) {
    int requiredCapacity = size + additionalCapacity;
    if (requiredCapacity > data.length) {
        int newCapacity = data.length == 0 ? 10 : data.length * 2;
        while (newCapacity < requiredCapacity) {
            newCapacity *= 2;
        }
        data = Arrays.copyOf(data, newCapacity);
    }
}

