    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    try {
        int strLength = str.length();
        int utf8Length = 0;
        for (int i = 0; i < strLength; i++) {
            char c = str.charAt(i);
            if (c < 0x80) {
                utf8Length++;
            } else if (c < 0x800) {
                utf8Length += 2;
            } else if (Character.isHighSurrogate(c)) {
                if (i + 1 < strLength && Character.isLowSurrogate(str.charAt(i + 1))) {
                    utf8Length += 4;
                    i++;
                } else {
                    throw new IllegalArgumentException("Invalid surrogate pair in input string");
                }
            } else {
                utf8Length += 3;
            }
        }

        LinkedBuffer buffer = lb;
        int bytesWritten = 0;
        for (int i = 0; i < strLength; i++) {
            char c = str.charAt(i);
            if (buffer.start + buffer.offset + bytesWritten >= buffer.limit) {
                buffer = buffer.next = session.nextBuffer();
                bytesWritten = 0;
            }
            if (c < 0x80) {
                buffer.buffer[buffer.offset + bytesWritten++] = (byte) c;
            } else if (c < 0x800) {
                buffer.buffer[buffer.offset + bytesWritten++] = (byte) (0xc0 | (c >> 6));
                buffer.buffer[buffer.offset + bytesWritten++] = (byte) (0x80 | (c & 0x3f));
            } else if (Character.isHighSurrogate(c)) {
                char lowSurrogate = str.charAt(++i);
                int codePoint = Character.toCodePoint(c, lowSurrogate);
                buffer.buffer[buffer.offset + bytesWritten++] = (byte) (0xf0 | (codePoint >> 18));
                buffer.buffer[buffer.offset + bytesWritten++] = (byte) (0x80 | ((codePoint >> 12) & 0x3f));
                buffer.buffer[buffer.offset + bytesWritten++] = (byte) (0x80 | ((codePoint >> 6) & 0x3f));
                buffer.buffer[buffer.offset + bytesWritten++] = (byte) (0x80 | (codePoint & 0x3f));
            } else {
                buffer.buffer[buffer.offset + bytesWritten++] = (byte) (0xe0 | (c >> 12));
                buffer.buffer[buffer.offset + bytesWritten++] = (byte) (0x80 | ((c >> 6) & 0x3f));
                buffer.buffer[buffer.offset + bytesWritten++] = (byte) (0x80 | (c & 0x3f));
            }
        }
        return lb;
    } catch (Exception e) {
        throw new RuntimeException("Error writing UTF-8 string to LinkedBuffer", e);
    }
}

