    int offset = buffer.start;
    byte[] data = buffer.buffer;

    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            if (offset == buffer.limit) {
                buffer = session.next(buffer, 1);
                data = buffer.buffer;
                offset = buffer.start;
            }
            data[offset++] = (byte) c;
        } else if (c < 0x800) {
            if (offset + 1 >= buffer.limit) {
                buffer = session.next(buffer, 2);
                data = buffer.buffer;
                offset = buffer.start;
            }
            data[offset++] = (byte) (0xc0 | (c >> 6));
            data[offset++] = (byte) (0x80 | (c & 0x3f));
        } else if (Character.isSurrogate(c)) {
            char c2 = str.charAt(++i);
            int codePoint = Character.toCodePoint(c, c2);
            if (offset + 3 >= buffer.limit) {
                buffer = session.next(buffer, 4);
                data = buffer.buffer;
                offset = buffer.start;
            }
            data[offset++] = (byte) (0xf0 | (codePoint >> 18));
            data[offset++] = (byte) (0x80 | ((codePoint >> 12) & 0x3f));
            data[offset++] = (byte) (0x80 | ((codePoint >> 6) & 0x3f));
            data[offset++] = (byte) (0x80 | (codePoint & 0x3f));
        } else {
            if (offset + 2 >= buffer.limit) {
                buffer = session.next(buffer, 3);
                data = buffer.buffer;
                offset = buffer.start;
            }
            data[offset++] = (byte) (0xe0 | (c >> 12));
            data[offset++] = (byte) (0x80 | ((c >> 6) & 0x3f));
            data[offset++] = (byte) (0x80 | (c & 0x3f));
        }
