public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || session == null || lb == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    int length = str.length();
    int size = 0;

    // Calculate the size needed to store the UTF-8 encoded bytes
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            size += 1;
        } else if (c < 0x800) {
            size += 2;
        } else if (Character.isSurrogate(c)) {
            if (i + 1 < length && Character.isSurrogatePair(c, str.charAt(i + 1))) {
                size += 4; // surrogate pair takes 4 bytes in UTF-8
                i++; // skip the next character as it's part of the surrogate pair
            } else {
                throw new IllegalArgumentException("Invalid surrogate character found");
            }
        } else {
            size += 3;
        }
    }

    // Ensure we have enough space in the buffer
    LinkedBuffer buffer = ensureCapacity(size, lb);

    // Write the UTF-8 bytes into the buffer
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            buffer = writeByte(c, session, buffer);
        } else if (c < 0x800) {
            buffer = writeByte(0xc0 | (c >> 6), session, buffer);
            buffer = writeByte(0x80 | (c & 0x3f), session, buffer);
        } else if (Character.isSurrogate(c)) {
            if (i + 1 < length && Character.isSurrogatePair(c, str.charAt(i + 1))) {
                int codePoint = Character.toCodePoint(c, str.charAt(i + 1));
                buffer = writeByte(0xf0 | (codePoint >> 18), session, buffer);
                buffer = writeByte(0x80 | ((codePoint >> 12) & 0x3f), session, buffer);
                buffer = writeByte(0x80 | ((codePoint >> 6) & 0x3f), session, buffer);
                buffer = writeByte(0x80 | (codePoint & 0x3f), session, buffer);
                i++; // skip the next character as it's part of the surrogate pair
            } else {
                throw new IllegalArgumentException("Invalid surrogate character found");
            }
        } else {
            buffer = writeByte(0xe0 | (c >> 12), session, buffer);
            buffer = writeByte(0x80 | ((c >> 6) & 0x3f), session, buffer);
            buffer = writeByte(0x80 | (c & 0x3f), session, buffer);
        }
    }

    return buffer;
}

private static LinkedBuffer ensureCapacity(int size, LinkedBuffer lb) {
    while (size > 0) {
        if (lb.offset + size <= lb.buffer.length) {
            return lb;
        } else {
            size -= (lb.buffer.length - lb.offset);
            lb = lb.next = new LinkedBuffer(lb.buffer.length); // Assuming LinkedBuffer has a constructor that takes the buffer length
        }
    }
    return lb;
}

private static LinkedBuffer writeByte(int value, WriteSession session, LinkedBuffer lb) {
    if (lb.offset >= lb.buffer.length) {
        lb = lb.next = new LinkedBuffer(lb.buffer.length); // Assuming LinkedBuffer has a constructor that takes the buffer length
    }
    lb.buffer[lb.offset++] = (byte) value;
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || session == null || lb == null) {
        throw new IllegalArgumentException("Input string, session, and buffer must not be null.");
    }

    try {
        int length = str.length();
        int offset = session.getWriterIndex();

        // Ensure we have enough space in the buffer
        while (length > 0) {
            int remaining = lb.capacity - offset;

            // If the remaining capacity is not enough to write the entire string, expand the buffer
            if (remaining == 0) {
                lb = lb.expand(session);
                offset = session.getWriterIndex();
                remaining = lb.capacity - offset;
            }

            int charsWritten = 0;
            while (charsWritten < remaining && charsWritten < length) {
                char ch = str.charAt(charsWritten);
                if (ch < 0x80) {
                    lb.buffer[offset + charsWritten] = (byte) ch;
                } else if (ch < 0x800) {
                    lb.buffer[offset + charsWritten++] = (byte) (0xC0 | (ch >> 6));
                    lb.buffer[offset + charsWritten] = (byte) (0x80 | (ch & 0x3F));
                } else {
                    lb.buffer[offset + charsWritten++] = (byte) (0xE0 | (ch >> 12));
                    lb.buffer[offset + charsWritten++] = (byte) (0x80 | ((ch >> 6) & 0x3F));
                    lb.buffer[offset + charsWritten] = (byte) (0x80 | (ch & 0x3F));
                }
                charsWritten++;
            }

            session.setWriterIndex(offset + charsWritten);
            offset = session.getWriterIndex();
            length -= charsWritten;
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to write UTF8 to LinkedBuffer", e);
    }

    return lb;
}

