private void enlarge(final int size) {
    if (size < 0) {
        throw new IllegalArgumentException("Size must be non-negative");
    }
    if (size == 0) {
        return; // No need to enlarge if no additional space is required
    }
    int currentCapacity = (this.data == null) ? 0 : this.data.length;
    int newCapacity = currentCapacity + size;
    if (newCapacity < currentCapacity) {
        throw new OutOfMemoryError("Requested size is too large");
    }
    byte[] newData = new byte[newCapacity];
    if (this.data != null) {
        System.arraycopy(this.data, 0, newData, 0, this.data.length);
    }
    this.data = newData;
}

