    if (size <= 0) {
        return; // No need to enlarge if size is zero or negative
    }
    int neededCapacity = (this.data == null) ? 0 : this.data.length;
    while (neededCapacity - this.length < size) {
        neededCapacity = (neededCapacity == 0) ? 64 : neededCapacity * 2;
    }
    byte[] newData = new byte[neededCapacity];
    if (this.data != null) {
        System.arraycopy(this.data, 0, newData, 0, this.length);
    }
    this.data = newData;
}

