public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null) {
        throw new NullPointerException("DataOutput cannot be null");
    }
    if (node == null) {
        return 0; // No content to write if the node is null
    }

    int totalSize = 0;
    while (node != null) {
        out.write(node.buffer, 0, node.offset);
        totalSize += node.offset;
        node = node.next;
    }

    return totalSize;
}

