        throw new IllegalArgumentException("DataOutput cannot be null");
    }
    byte[] buffer = node.buffer;
    int offset = node.start;
    int length = node.pos - node.start;
    out.write(buffer, offset, length);
    totalContentSize += length;
    node = node.next;
}
return totalContentSize;

int totalContentSize = 0;
while (node != null) {
    if (out == null) {
        throw new IllegalArgumentException("DataOutput cannot be null");
    }
    out.write(node.buffer, 0, node.offset);
    totalContentSize += node.offset;
