}
return totalContentSize;

int totalContentSize = 0;
while (node != null) {
    if (out == null) {
        throw new IOException("DataOutput cannot be null");
    }
    try {
        out.write(node.buffer, 0, node.offset);
        totalContentSize += node.offset;
    } catch (IOException e) {
        throw new IOException("Error writing to DataOutput", e);
    }
    node = node.next;
}
