public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("DataOutput cannot be null");
    }
    if (node == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    int totalSize = 0;
    while (node != null) {
        if (node.offset < 0 || node.offset > node.buffer.length) {
            throw new IllegalStateException("Invalid offset in LinkedBuffer");
        }
        if (node.start < 0 || node.start > node.offset) {
            throw new IllegalStateException("Invalid start in LinkedBuffer");
        }

        out.write(node.buffer, node.start, node.offset - node.start);
        totalSize += node.offset - node.start;
        node = node.next;
    }

    return totalSize;
}

