public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 1) {
        return 2; // The smallest prime number
    }

    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++; // Ensure the candidate is odd
    }

    while (!isPrime(candidate)) {
        candidate += 2; // Increment by 2 to check only odd numbers
    }

    // Check if the candidate is within 11% of desiredCapacity if desiredCapacity >= 1000
    if (desiredCapacity >= 1000 && candidate > desiredCapacity * 1.11) {
        candidate = findClosestPrime(desiredCapacity);
    }

    return candidate;
}

private static boolean isPrime(int number) {
    if (number <= 1) {
        return false;
    }
    if (number <= 3) {
        return true;
    }
    if (number % 2 == 0 || number % 3 == 0) {
        return false;
    }
    for (int i = 5; i * i <= number; i += 6) {
        if (number % i == 0 || number % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

private static int findClosestPrime(int desiredCapacity) {
    int lowerBound = (int) (desiredCapacity * 0.89);
    int upperBound = (int) (desiredCapacity * 1.11);

    for (int i = desiredCapacity; i <= upperBound; i++) {
        if (isPrime(i)) {
            return i;
        }
    }

    for (int i = desiredCapacity - 1; i >= lowerBound; i--) {
        if (isPrime(i)) {
            return i;
        }
    }

    return desiredCapacity; // Fallback, should not reach here
}

