    for (int i = 0; i < length; i++) {
        char currentChar = str.charAt(i);
        if (currentChar == '\\') {
            if (i + 1 >= length) {
                throw new Exception("Invalid escape sequence");
            }
            char nextChar = str.charAt(i + 1);
            switch (nextChar) {
                case 'n':
                    output.append('\n');
                    break;
                case 'r':
                    output.append('\r');
                    break;
                case 't':
                    output.append('\t');
