private int removeUnusedNodesRecursive(CategoryNode node) {
    if (node == null) {
        return 0;
    }

    if (node.isActive() && node.hasChildren()) {
        int activeChildrenCount = 0;
        Iterator<CategoryNode> iterator = node.getChildren().iterator();
        while (iterator.hasNext()) {
            CategoryNode child = iterator.next();
            int childCount = removeUnusedNodesRecursive(child);
            if (childCount == 0 && !child.isActive()) {
                iterator.remove();
            } else {
                activeChildrenCount += childCount + (child.isActive() ? 1 : 0);
            }
        }
        return activeChildrenCount;
    } else if (!node.isActive() && !node.hasChildren()) {
        return 0;
    } else {
        return 1;
    }
}

