        if (child.isActive()) {
            removedCount += removeUnusedNodesRecursive(child);
        } else {
            node.removeChild(child);
            removedCount++;
        }
    }
    return removedCount;
}

protected int removeUnusedNodes(){
    if (this.root == null) {
        return 0;
    }

    int count = removeUnusedNodesHelper(this.root);
    return count;
}

private int removeUnusedNodesHelper(CategoryNode node) {
    if (node == null) {
        return 0;
    }

    int removedCount = 0;
    List<CategoryNode> activeChildren = new ArrayList<>();

    for (CategoryNode child : node.getChildren()) {
        int childRemovedCount = removeUnusedNodesHelper(child);
        removedCount += childRemovedCount;
        if (child.isActive() || childRemovedCount > 0) {
            activeChildren.add(child);
        }
    }

    node.setChildren(activeChildren);
    if (!node.isActive() && activeChildren.isEmpty()) {
        return removedCount + 1;
    }

    return removedCount;
}

