private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null || start == null || stop == null) {
        throw new IllegalArgumentException("Predicate, start, and stop nodes cannot be null");
    }

    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);

    while (!circulator.getNode().equals(stop)) {
        if (predicate.test(circulator.getNode())) {
            return circulator;
        }
        circulator.next();
    }

    return circulator;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (start == null || stop == null || predicate == null) {
        throw new IllegalArgumentException("Start node, stop node, and predicate must not be null.");
    }

    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);

    while (!circulator.getNode().equals(stop)) {
        try {
            Node currentNode = circulator.getNode();
            if (predicate.test(currentNode)) {
                return circulator;
            }
            circulator.toNext();
        } catch (Exception e) {
            // Handle any unexpected exceptions during traversal
            throw new RuntimeException("An error occurred while traversing the outer face.", e);
        }
    }

    return circulator; // Return circulator to the stop node
}

