    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }

    if (tour.isEmpty()) {
        throw new IllegalArgumentException("Tour cannot be empty");
    }

    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = graph.getEdgeSource(edgeList.get(0));
    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);

    Set<E> visitedEdges = new HashSet<>();
    visitedEdges.add(edgeList.get(0));

    V currentVertex = startVertex;
    while (visitedEdges.size() < tour.size()) {
        for (E edge : tour) {
            if (!visitedEdges.contains(edge)) {
                V source = graph.getEdgeSource(edge);
                V target = graph.getEdgeTarget(edge);

                if (source.equals(currentVertex) || target.equals(currentVertex)) {
                    visitedEdges.add(edge);
                    currentVertex = source.equals(currentVertex) ? target : source;
                    vertexList.add(currentVertex);
                    break;
                }
            }
        }
    }

    return new GraphPathImpl<>(graph, vertexList.get(0), vertexList.get(vertexList.size() - 1), vertexList, edgeList, graph.getType().isDirected() ? calculateDirectedPathWeight(graph, edgeList) : calculateUndirectedPathWeight(graph, edgeList));
}

private double calculateDirectedPathWeight(Graph<V,E> graph, List<E> edgeList) {
    double weight = 0.0;
    for (E edge : edgeList) {
        weight += graph.getEdgeWeight(edge);
    }
    return weight;
}

private double calculateUndirectedPathWeight(Graph<V,E> graph, List<E> edgeList) {
    return calculateDirectedPathWeight(graph, edgeList);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, Collections.emptyList(), 0.0);
    }

    List<E> pathEdges = new ArrayList<>(tour);
    List<V> pathVertices = new ArrayList<>();

    V startVertex = graph.getEdgeSource(pathEdges.get(0));
    pathVertices.add(startVertex);

    Map<V, List<E>> edgeMap = new HashMap<>();
    for (E edge : pathEdges) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        edgeMap.computeIfAbsent(source, k -> new ArrayList<>()).add(edge);
        edgeMap.computeIfAbsent(target, k -> new ArrayList<>()).add(edge);
    }

    try {
        V currentVertex = startVertex;
        while (!pathEdges.isEmpty()) {
            E currentEdge = pathEdges.stream()
                                     .filter(e -> graph.getEdgeSource(e).equals(currentVertex) || graph.getEdgeTarget(e).equals(currentVertex))
                                     .findFirst()
                                     .orElseThrow(() -> new IllegalArgumentException("Tour is not a valid path"));

            pathEdges.remove(currentEdge);
            currentVertex = graph.getEdgeSource(currentEdge).equals(currentVertex) ? graph.getEdgeTarget(currentEdge) : graph.getEdgeSource(currentEdge);
            pathVertices.add(currentVertex);
        }
    } catch (NoSuchElementException e) {
        throw new IllegalArgumentException("Tour is not a valid path", e);
    }

    return new GraphPathImpl<>(graph, startVertex, pathVertices, graph.getType().isWeighted() ? pathEdges.stream().mapToDouble(graph::getEdgeWeight).sum() : 0.0);
}

