        Symbol existingSymbol = constantPool.get(i);
        if (existingSymbol instanceof NameAndTypeSymbol) {
            NameAndTypeSymbol existingNameAndType = (NameAndTypeSymbol) existingSymbol;
            if (existingNameAndType.name.equals(name) && existingNameAndType.descriptor.equals(descriptor)) {
                return i;
            }
        }
    }

    NameAndTypeSymbol newSymbol = new NameAndTypeSymbol(name, descriptor);
    constantPool.add(newSymbol);
    return constantPool.size() - 1;
}

