    }
    StringBuilder result = new StringBuilder();
    boolean isEscaped = false;
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (isEscaped) {
            if (c == 'b') {
                result.append('\b');
            } else if (c == 'f') {
                result.append('\f');
            } else if (c == 'n') {
                result.append('\n');
            } else if (c == 'r') {
                result.append('\r');
            } else if (c == 't') {
                result.append('\t');
            } else if (c == '"') {
                result.append('"');
            } else if (c == '\\') {
                result.append('\\');
            } else {
                // Invalid escape sequence, throw an exception
                throw new IllegalArgumentException("Invalid escape sequence: '\\" + c + "'");
            }
            isEscaped = false;
        } else if (c == '\\') {
            isEscaped = true;
        } else {
            result.append(c);
        }
    }
    if (isEscaped) {
        throw new IllegalArgumentException("Invalid escape sequence at end of string");
    }
    return result.toString();
}

private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    // Assuming DOT escape sequences are represented by a backslash followed by the escaped character
    // For example, "\n" for newline, "\"" for double quote, etc.
    StringBuilder result = new StringBuilder();
    boolean isEscaped = false;
    for (int i = 0; i < input.length(); i++) {
        char currentChar = input.charAt(i);
        if (isEscaped) {
            // Handle common escape sequences
            switch (currentChar) {
                case 'n':
                    result.append('\n');
                    break;
                case 't':
                    result.append('\t');
                    break;
                case 'r':
                    result.append('\r');
                    break;
                case 'b':
                    result.append('\b');
                    break;
                case 'f':
                    result.append('\f');
                    break;
                case '\\':
                    result.append('\\');
                    break;
                case '"':
                    result.append('"');
                    break;
                default:
                    // Treat unknown escape sequences as-is
                    result.append('\\').append(currentChar);
                    break;
            }
            isEscaped = false;
        } else if (currentChar == '\\') {
            isEscaped = true;
        } else {
            result.append(currentChar);
        }
    }
    return result.toString();
}

