private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null) {
        throw new IllegalArgumentException("bucketsByLabel and labels cannot be null");
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("minLabel is out of bounds");
    }
    Set<Integer> minLabelBucket = bucketsByLabel.get(minLabel);
    if (minLabelBucket == null) {
        throw new IllegalArgumentException("Bucket for minLabel is null");
    }
    Set<Integer> zeroLabelBucket = bucketsByLabel.get(0);
    if (zeroLabelBucket == null) {
        throw new IllegalArgumentException("Bucket for label 0 is null");
    }

    for (Integer vertex : minLabelBucket) {
        if (vertex == null || vertex < 0 || vertex >= labels.size()) {
            throw new IllegalArgumentException("Invalid vertex in bucket");
        }
        labels.set(vertex, 0);
        zeroLabelBucket.add(vertex);
    }

    minLabelBucket.clear();
}

