public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        throw new IllegalArgumentException("Table and JScrollPane must not be null");
    }
    if (row < 0 || row >= table.getRowCount()) {
        throw new IllegalArgumentException("Row index is out of bounds");
    }

    try {
        // Select the specified row
        table.setRowSelectionInterval(row, row);

        // Scroll to the newly selected row
        Rectangle rect = table.getCellRect(row, 0, true);
        pane.getViewport().scrollRectToVisible(rect);

        // Repaint the table with a small delay to ensure proper rendering
        table.repaint(100);
    } catch (Exception e) {
        e.printStackTrace();
    }
}

public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        throw new IllegalArgumentException("Table and JScrollPane must not be null");
    }
    if (row < 0 || row >= table.getRowCount()) {
        throw new IllegalArgumentException("Row index out of bounds");
    }

    table.setRowSelectionInterval(row, row);
    Rectangle cellRect = table.getCellRect(row, 0, true);
    pane.scrollRectToVisible(cellRect);

    // Delayed repaint to ensure the table properly paints the newly selected row
    table.repaint(cellRect);

    try {
        // Delay for a short period to allow the table to repaint
        Thread.sleep(100);
    } catch (InterruptedException e) {
        Thread.currentThread().interrupt();
    }

    table.repaint(cellRect);
}

