private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    int index = 0;
    if (descriptor.charAt(0) == '(') {
        // Method descriptor, process argument types
        index = 1; // Skip the opening parenthesis
        while (descriptor.charAt(index) != ')') {
            index = popType(descriptor, index);
        }
        index++; // Skip the closing parenthesis
    }

    // If there's a return type, process it
    if (index < descriptor.length()) {
        popType(descriptor, index);
    }
}

private int popType(final String descriptor, int index) {
    switch (descriptor.charAt(index)) {
        case 'B': // byte
        case 'C': // char
        case 'D': // double
        case 'F': // float
        case 'I': // int
        case 'J': // long
        case 'S': // short
        case 'Z': // boolean
            index++; // Single character types
            break;
        case 'L': // Object
            index = descriptor.indexOf(';', index) + 1;
            if (index == 0) {
                throw new IllegalArgumentException("Invalid object descriptor: " + descriptor);
            }
            break;
        case '[': // Array
            do {
                index++;
            } while (descriptor.charAt(index) == '[');
            index = popType(descriptor, index); // Recurse for the array element type
            break;
        default:
            throw new IllegalArgumentException("Invalid descriptor character: " + descriptor.charAt(index));
    }
    return index;
}

