    String[] relativeParts = relativePath.split("/");

    // Use a stack to build the final path
    Stack<String> pathStack = new Stack<>();
    String[] pathParts = path.split("/");

    // Add all parts of the original path to the stack
    for (String part : pathParts) {
        if (!part.isEmpty()) { // Skip empty parts (in case of leading/trailing slashes)
            pathStack.push(part);
        }
    }

    // Process each part of the relative path
    for (String part : relativeParts) {
        if (part.equals("..")) {
            // Move up one directory if possible
            if (!pathStack.isEmpty()) {
                pathStack.pop();
            }
        } else if (!part.equals("") && !part.equals(".")) {
            // Add the directory to the stack
            pathStack.push(part);
        }
        // Ignore "." and empty parts (which can occur due to consecutive slashes)
    }

    // Build the final path from the stack
    StringBuilder resultPath = new StringBuilder();
    while (!pathStack.isEmpty()) {
        resultPath.insert(0, pathStack.pop());
        if (!pathStack.isEmpty()) {
            resultPath.insert(0, "/");
        }
    }

    // Ensure the path starts with a slash if the original path did
    if (path.startsWith("/") && !resultPath.toString().startsWith("/")) {
        resultPath.insert(0, "/");
    }

