public int readTag() throws IOException {
    // Attempt to read the next byte from the input stream
    int firstByte = input.read();

    // If the first byte is -1, it indicates the end of the stream (EOF)
    if (firstByte == -1) {
        return 0;
    }

    // Check if the tag is a single byte (most common case)
    if ((firstByte & 0x80) == 0) {
        return firstByte;
    }

    // Otherwise, it's a multi-byte tag
    int result = firstByte & 0x7F;
    int shift = 7;

    // Read subsequent bytes to fully reconstruct the tag
    while (true) {
        int b = input.read();
        if (b == -1) {
            throw new IOException("Invalid tag: reached EOF in the middle of a multi-byte tag");
        }
        result |= (b & 0x7F) << shift;
        shift += 7;
        if ((b & 0x80) == 0) {
            break;
        }
    }

    // Verify that the tag is not zero
    if (result == 0) {
        throw new IOException("Invalid tag: zero is not a valid tag number");
    }

    return result;
}

